std::vector<Node> nodes;
for (auto it = rt.finite_vertices_begin(); it != rt.finite_vertices_end(); ++it) {
    Node node;
    node.position = it->point();
    node.velocity = it->velocity();
    node.mass = it->mass();
    if (it->is_boundary()) {
        node.type = Node::BOUNDARY;
    } else if (it->degree() < 4) {
        node.type = Node::SURFACE;
    } else if (it->degree() < 8) {
        node.type = Node::TRANSITION;
    } else {
        node.type = Node::CORE;
    }
    if (it->degree() > 0) {
        double edge_length = CGAL::sqrt(CGAL::squared_distance(it->point(), it->neighbor(0)->point()));
        if (edge_length > threshold) {
            node.type = Node::SURFACE;
        }
    }
    nodes.push_back(node);
}
return nodes;

